quirements":[],"qualis_requirement":null,"authorship_requirement":null,"document_requirements":[],"date_window":null,"presentation_formats":[],"event_scopes":[],"publication_scopes":[],"event_organizer":null,"subject_area_requirement":null,"evidence":{"official_url":"https://s3.amazonaws.com/cdn.concursos.selecting.com.br/edital/1/43/7e864f52e890b4bea59cef257c3bd45c.pdf","page":"14","document_sha256":"3b0a75aeba88d11f6afa2113c1eb8fe8705e74e9b6f066ca0c06e51005ecad16","excerpt":"Publicações de texto integral em periódicos com corpo editorial.","source_status":"Confirmado em fonte oficial"},"unknown_data":[],"warnings":["AUTHORSHIP_AFFECTS_SCORE","DOCUMENTARY_VALIDATION_REQUIRED"],"review":{"automated_technical_review":true,"human_review":false,"decision":"APPROVE","method":"OFFICIAL_SOURCE_REEXTRACTION","reviewer":"codex-primary-agent"},"source_metadata":{"classification_reason":"Publicações de texto integral em periódicos com corpo editorial.","requirement_label":"Texto integral em periódico com corpo editorial; resumo não conta","review_messages":[],"source_notes":null},"mapping_hash":"b7e892ec7e5e8b3457a3f5830f05082ec65cbd7b23230b6ebdf8a216883fb6c8"}]$refresh_rules$::jsonb) as item(
    source_rule_id text, source_process_id text, release_code text, core_version text,
    family text, production_type text, accepted_production_types jsonb,
    initial_eligibility text, mapping_status text, published_for_engine boolean,
    mapping_confidence text, matrix_row integer, scope jsonb, condition_groups jsonb,
    score_formula jsonb, indexing_requirements jsonb, qualis_requirement jsonb,
    authorship_requirement jsonb, document_requirements jsonb, date_window jsonb,
    presentation_formats jsonb, event_scopes jsonb, publication_scopes jsonb,
    event_organizer jsonb, subject_area_requirement jsonb, evidence jsonb,
    unknown_data jsonb, warnings jsonb, review jsonb, source_metadata jsonb,
    mapping_hash text
  )
)
insert into public.scientific_rules (
  import_batch_id, edict_id, source_rule_id, source_process_id, release_code, core_version,
  family, production_type, accepted_production_types, initial_eligibility, mapping_status,
  published_for_engine, mapping_confidence, matrix_row, scope, condition_groups, score_formula,
  indexing_requirements, qualis_requirement, authorship_requirement, document_requirements,
  date_window, presentation_formats, event_scopes, publication_scopes, event_organizer,
  subject_area_requirement, evidence, unknown_data, warnings, review, source_metadata, mapping_hash
)
select batch.id, edict.id, item.source_rule_id, item.source_process_id, item.release_code,
  item.core_version, item.family, item.production_type, item.accepted_production_types,
  item.initial_eligibility, item.mapping_status, item.published_for_engine,
  item.mapping_confidence, item.matrix_row, item.scope, item.condition_groups,
  item.score_formula, item.indexing_requirements, item.qualis_requirement,
  item.authorship_requirement, item.document_requirements, item.date_window,
  item.presentation_formats, item.event_scopes, item.publication_scopes,
  item.event_organizer, item.subject_area_requirement, item.evidence, item.unknown_data,
  item.warnings, item.review, item.source_metadata, item.mapping_hash
from source_rules item
join public.edicts edict on edict.source_process_id = item.source_process_id
join public.scientific_import_batches batch on batch.batch_key = 'SCIENTIFIC-REFRESH-2026-08-29-v1'
on conflict (release_code, source_rule_id) do nothing;

update public.edicts edict
set coverage_status = assessment.assessment_status
from public.scientific_coverage_assessments assessment
where assessment.release_code = 'APP-SCIENTIFIC-REFRESH-2026-08-29-v1'
  and assessment.edict_id = edict.id;

update public.scientific_import_batches
set status = 'APPLIED', completed_at = now(), counts = counts || jsonb_build_object(
  'applied_edicts', (select count(*) from public.edicts where source_process_id in (select jsonb_array_elements_text('["2027-SP-UNITAU-PRPPG","2027-SP-EINSTEIN-VUNESP","2027-CE-ICC-COREME","2027-RS-UFCSPA-FUNDMED","2027-RS-HCPA-FUNDMED","2027-RS-HMV-FUNDMED","2027-SP-FMJ-VUNESP","2027-SP-BOS-VUNESP","2027-RO-HBAP-CEMETRON-SESAU","2027-RJ-HUV-COREME","2027-PR-HZSL-AMP","2027-PR-SJP-SMS","2027-PR-SANTA-CASA-PG-AMP","2027-SP-SANTA-CASA-RP-VUNESP","2027-NACIONAL-OPTY-SELECTING","2027-CE-APEC-ACEP","2027-SP-ABHU-UNIMAR","2027-RJ-CEPOA-CONSESP","2027-GO-FUBOG-SELECTING","2027-PR-HUC-PUCPR","2027-RJ-UERJ-CEPUERJ","2027-ES-HSRC-IBEST"]'::jsonb))),
  'applied_assessments', (select count(*) from public.scientific_coverage_assessments where release_code = 'APP-SCIENTIFIC-REFRESH-2026-08-29-v1'),
  'applied_rules', (select count(*) from public.scientific_rules where release_code = 'APP-SCIENTIFIC-REFRESH-2026-08-29-v1')
)
where batch_key = 'SCIENTIFIC-REFRESH-2026-08-29-v1';

do $$
declare
  edict_count integer;
  assessment_count integer;
  rule_count integer;
  rule_process_count integer;
  active_pre_2025 integer;
begin
  select count(*) into edict_count
  from public.edicts
  where source_process_id in (select jsonb_array_elements_text('["2027-SP-UNITAU-PRPPG","2027-SP-EINSTEIN-VUNESP","2027-CE-ICC-COREME","2027-RS-UFCSPA-FUNDMED","2027-RS-HCPA-FUNDMED","2027-RS-HMV-FUNDMED","2027-SP-FMJ-VUNESP","2027-SP-BOS-VUNESP","2027-RO-HBAP-CEMETRON-SESAU","2027-RJ-HUV-COREME","2027-PR-HZSL-AMP","2027-PR-SJP-SMS","2027-PR-SANTA-CASA-PG-AMP","2027-SP-SANTA-CASA-RP-VUNESP","2027-NACIONAL-OPTY-SELECTING","2027-CE-APEC-ACEP","2027-SP-ABHU-UNIMAR","2027-RJ-CEPOA-CONSESP","2027-GO-FUBOG-SELECTING","2027-PR-HUC-PUCPR","2027-RJ-UERJ-CEPUERJ","2027-ES-HSRC-IBEST"]'::jsonb));
  if edict_count <> 22 then raise exception 'Expected 22 refresh edicts, found %.', edict_count; end if;

  select count(*) into assessment_count from public.scientific_coverage_assessments where release_code = 'APP-SCIENTIFIC-REFRESH-2026-08-29-v1';
  if assessment_count <> 22 then raise exception 'Expected 22 refresh assessments, found %.', assessment_count; end if;

  select count(*), count(distinct source_process_id) into rule_count, rule_process_count
  from public.scientific_rules where release_code = 'APP-SCIENTIFIC-REFRESH-2026-08-29-v1';
  if rule_count <> 21 then raise exception 'Expected 21 refresh rules, found %.', rule_count; end if;
  if rule_process_count <> 11 then raise exception 'Expected 11 rule processes, found %.', rule_process_count; end if;

  select count(*) into active_pre_2025 from public.edicts where entry_year < 2025 and active;
  if active_pre_2025 <> 0 then raise exception 'Expected zero active pre-2025 edicts, found %.', active_pre_2025; end if;
end $$;
